                <>
                  {item.icon && <span className="mr-2">{item.icon}</span>}
                  {item.label}
                  {item.action ? (
                    <ShortcutDisplay action={item.action} as={DropdownMenuShortcut} />
                  ) : null}
                </>
              )}
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>

        {handleThemeChange && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuSub>
              <DropdownMenuSubTrigger>
                <SunIcon className="mr-2 size-4" />
                <span>Theme</span>
